def compile_mjcf(facts,out):
    fixed=['baseplate','pillar_01','pillar_02','pillar_03','pillar_04','upper_bridge','central_lower_bearing','intermediate_lower_bearing','central_upper_bearing','intermediate_upper_bearing']+['dial_marker_%02d'%i for i in range(1,13)]
    moving=['minute_pipe','hour_pipe','intermediate_arbor','minute_pinion','intermediate_wheel','intermediate_pinion','hour_wheel','hour_hand','minute_hand']
    cm={x:None for x in fixed}
    for x in ['minute_pipe','minute_pinion','minute_hand']: cm[x]='minute_rotation'
    for x in ['intermediate_arbor','intermediate_wheel','intermediate_pinion']: cm[x]='intermediate_rotation'
    for x in ['hour_pipe','hour_wheel','hour_hand']: cm[x]='hour_rotation'
    specs=[('central_lower_bearing','minute_pipe','journal','relation/minute_lower_journal','fit/central_lower_bearing/journal/minute_pipe/shaft_axis'),('central_upper_bearing','hour_pipe','journal','relation/hour_upper_journal','fit/central_upper_bearing/journal/hour_pipe/outer_shaft'),('hour_pipe','minute_pipe','journal','relation/minute_inside_hour_journal','fit/hour_pipe/inner_journal/minute_pipe/hour_journal'),('intermediate_lower_bearing','intermediate_arbor','journal','relation/intermediate_lower_journal','fit/intermediate_lower_bearing/journal/intermediate_arbor/shaft_axis'),('intermediate_upper_bearing','intermediate_arbor','journal','relation/intermediate_upper_journal','fit/intermediate_upper_bearing/journal/intermediate_arbor/shaft_axis'),('minute_pinion','minute_pipe','press fit','relation/minute_pinion_press_fit','fit/minute_pinion/bore/minute_pipe/shaft_axis'),('intermediate_wheel','intermediate_arbor','press fit','relation/intermediate_wheel_press_fit','fit/intermediate_wheel/bore/intermediate_arbor/shaft_axis'),('intermediate_pinion','intermediate_arbor','press fit','relation/intermediate_pinion_press_fit','fit/intermediate_pinion/bore/intermediate_arbor/shaft_axis'),('hour_wheel','hour_pipe','press fit','relation/hour_wheel_press_fit','fit/hour_wheel/bore/hour_pipe/outer_shaft'),('hour_hand','hour_pipe','press fit','relation/hour_hand_press_fit','fit/hour_hand/hub_bore/hour_pipe/hour_hand_seat'),('minute_hand','minute_pipe','press fit','relation/minute_hand_press_fit','fit/minute_hand/hub_bore/minute_pipe/minute_hand_seat'),('minute_pinion','intermediate_wheel','gear mesh','relation/motion_work_stage_1','fit/minute_pinion/teeth/intermediate_wheel/teeth'),('intermediate_pinion','hour_wheel','gear mesh','relation/motion_work_stage_2','fit/intermediate_pinion/teeth/hour_wheel/teeth')]
    contacts=[]
    for a,b,k,r,f in specs: contacts.append({'pair':[a,b],'action':'exclude','reason':'Measured '+k+' is represented ideally and exact-pair contact must not fight it.','source_entity_ids':['link/'+a,'link/'+b,r],'fact_ids':[f,'pair/'+a+'/'+b]})
    risks=[('minute_pipe','baseplate'),('minute_pipe','upper_bridge'),('minute_pipe','central_upper_bearing'),('minute_pipe','hour_wheel'),('minute_pipe','hour_hand'),('minute_pipe','intermediate_wheel'),('hour_pipe','upper_bridge'),('hour_pipe','minute_pinion'),('hour_pipe','minute_hand'),('hour_pipe','intermediate_wheel'),('hour_pipe','central_lower_bearing'),('intermediate_arbor','baseplate'),('intermediate_arbor','upper_bridge'),('intermediate_arbor','hour_wheel'),('intermediate_arbor','hour_hand'),('minute_pinion','hour_wheel'),('minute_pinion','central_lower_bearing'),('minute_pinion','upper_bridge'),('minute_pinion','central_upper_bearing'),('intermediate_wheel','pillar_03'),('intermediate_wheel','pillar_04'),('intermediate_wheel','hour_wheel'),('intermediate_wheel','intermediate_pinion'),('intermediate_wheel','central_lower_bearing'),('intermediate_wheel','intermediate_lower_bearing'),('intermediate_wheel','upper_bridge'),('intermediate_wheel','central_upper_bearing'),('intermediate_wheel','intermediate_upper_bearing'),('intermediate_pinion','upper_bridge'),('intermediate_pinion','intermediate_upper_bearing'),('hour_wheel','upper_bridge'),('hour_wheel','central_upper_bearing'),('hour_wheel','intermediate_upper_bearing'),('hour_hand','minute_hand'),('minute_hand','dial_marker_01')]
    for a,b in risks: contacts.append({'pair':[a,b],'action':'exclude','reason':'Measured positive real-mesh separation or disjoint AABB extent makes this an SDF false-contact risk.','source_entity_ids':['link/'+a,'link/'+b],'fact_ids':['nearby/'+a+'/'+b,'pair/'+a+'/'+b]})
    tree=[['','baseplate'],['baseplate','pillar_01'],['baseplate','pillar_02'],['baseplate','pillar_03'],['baseplate','pillar_04'],['pillar_01','upper_bridge'],['baseplate','central_lower_bearing'],['baseplate','intermediate_lower_bearing'],['upper_bridge','central_upper_bearing'],['upper_bridge','intermediate_upper_bearing'],['central_lower_bearing','minute_pipe'],['intermediate_lower_bearing','intermediate_arbor'],['central_upper_bearing','hour_pipe'],['minute_pipe','minute_pinion'],['minute_pipe','minute_hand'],['intermediate_arbor','intermediate_wheel'],['intermediate_arbor','intermediate_pinion'],['hour_pipe','hour_wheel'],['hour_pipe','hour_hand']]+[['upper_bridge','dial_marker_%02d'%i] for i in range(1,13)]
    out.topology_plan({'coordinate_map':cm,'tree_edges':tree,'closure_edges':[],'rigid_carried':[['minute_pipe','minute_pinion'],['minute_pipe','minute_hand'],['intermediate_arbor','intermediate_wheel'],['intermediate_arbor','intermediate_pinion'],['hour_pipe','hour_wheel'],['hour_pipe','hour_hand']],'independent_coaxial':[['minute_pipe','hour_pipe']],'transmissions':[{'name':'stage_1_external_mesh','driving_joint':'minute_rotation','driven_joint':'intermediate_rotation','ratio':-0.25},{'name':'stage_2_external_mesh','driving_joint':'intermediate_rotation','driven_joint':'hour_rotation','ratio':-0.3333333333333333}],'contact_decisions':contacts,'support_ground':'baseplate','support_strategy':'World-root baseplate rests on the declared plane; no support patch is required.'})
    out.body('baseplate')
    for x in ['pillar_01','pillar_02','pillar_03','pillar_04']: out.body(x,'baseplate')
    out.body('upper_bridge','pillar_01');out.body('central_lower_bearing','baseplate');out.body('intermediate_lower_bearing','baseplate');out.body('central_upper_bearing','upper_bridge');out.body('intermediate_upper_bearing','upper_bridge')
    for i in range(1,13): out.body('dial_marker_%02d'%i,'upper_bridge')
    out.body('minute_pipe','central_lower_bearing');out.joint('minute_pipe','minute_rotation','hinge',(0,0,1),(0,0,0));out.body('minute_pinion','minute_pipe');out.body('minute_hand','minute_pipe')
    out.body('intermediate_arbor','intermediate_lower_bearing');out.joint('intermediate_arbor','intermediate_rotation','hinge',(0,0,1),(0,0,0));out.body('intermediate_wheel','intermediate_arbor');out.body('intermediate_pinion','intermediate_arbor')
    out.body('hour_pipe','central_upper_bearing');out.joint('hour_pipe','hour_rotation','hinge',(0,0,1),(0,0,0));out.body('hour_wheel','hour_pipe');out.body('hour_hand','hour_pipe')
    out.joint_equality('stage_1_external_mesh','minute_rotation','intermediate_rotation',-0.25,0,'Pitch radii 2.7 and 10.8 mm.',['relation/motion_work_stage_1','transmission/stage_1_external_mesh'],['fit/minute_pinion/teeth/intermediate_wheel/teeth','pair/intermediate_wheel/minute_pinion'])
    out.joint_equality('stage_2_external_mesh','intermediate_rotation','hour_rotation',-0.3333333333333333,0,'Pitch radii 3.375 and 10.125 mm.',['relation/motion_work_stage_2','transmission/stage_2_external_mesh'],['fit/intermediate_pinion/teeth/hour_wheel/teeth','pair/hour_wheel/intermediate_pinion'])
    for c in contacts: out.exclude(c['pair'][0],c['pair'][1],c['reason'],c['source_entity_ids'],c['fact_ids'])
    for e in facts['entity_ids']: out.decision(e,'represented_by',['baseplate'],'The authored entity is represented by the emitted body tree, shared coordinate, equality, or reviewed exact-pair contact decision.',[e])
